SALVAMENTO_COMPACTO_PATCH = r'''
# HISTÓRICO COMPACTADO — patch aplicado após resiliência anterior.
_compact_insert_anchor = '# Ferramentas de recuperação são renderizadas no menu lateral padronizado.\n'
_compact_impl = "\n# =====================================================\n# HISTÓRICO COMPACTADO — NÃO ALTERA REGRAS DE CÁLCULO.\n# =====================================================\nimport base64 as _mrp_b64\nimport gzip as _mrp_gzip\nimport hashlib as _mrp_hash\n\n_mrp_compact_fields = (\"mrp_geral\", \"projecao_semanal\", \"demanda_projeto\", \"compra_mrp\", \"compras\", \"fabricacao\")\n\ndef _mrp_compact_snapshot(payload):\n    if payload.get(\"compressed_payload\"):\n        return payload\n    key = str(payload.get(\"calculation_key\") or \"\").strip()\n    if not re.fullmatch(r\"[0-9a-f]{64}\", key):\n        raise ValueError(\"Identificador de processamento ausente ou inválido.\")\n    sections = {field: payload.get(field) or [] for field in _mrp_compact_fields}\n    if any(not isinstance(data, list) for data in sections.values()):\n        raise ValueError(\"Formato inválido de uma das seções do MRP.\")\n    raw = json.dumps(sections, ensure_ascii=False, separators=(\",\", \":\"), default=str).encode(\"utf-8\")\n    packed = _mrp_gzip.compress(raw, compresslevel=6, mtime=0)\n    return {\n        \"semana_mrp\": payload.get(\"semana_mrp\"),\n        \"usuario\": str(payload.get(\"usuario\") or \"Não informado\"),\n        \"calculation_key\": key,\n        \"compressed_payload\": _mrp_b64.b64encode(packed).decode(\"ascii\"),\n    }\n\n_mrp_uncompressed_get = _sb_get\ndef _sb_get(params=None):\n    rows = _mrp_uncompressed_get(params)\n    for row in rows:\n        packed = row.pop(\"compressed_payload\", None)\n        if not packed:\n            continue\n        try:\n            content = json.loads(_mrp_gzip.decompress(_mrp_b64.b64decode(packed, validate=True)))\n            if not isinstance(content, dict):\n                raise ValueError(\"Estrutura de histórico inválida.\")\n            if any(not isinstance(content.get(field), list) for field in _mrp_compact_fields):\n                raise ValueError(\"Histórico compactado incompleto.\")\n            row.update(content)\n        except Exception as error:\n            raise RuntimeError(f\"Histórico MRP {row.get('id', '')} não pôde ser descompactado: {error}\") from error\n    return rows\n\ndef _mrp_lookup_saved_fast(key):\n    response = requests.get(\n        f\"{SUPABASE_URL}/rest/v1/mrp_snapshots\",\n        headers=_sb_headers(),\n        params={\"select\": \"id,created_at\", \"calculation_key\": f\"eq.{key}\", \"limit\": \"1\"},\n        timeout=(5, 9),\n    )\n    if response.status_code == 401 and _refresh_supabase_session():\n        response = requests.get(\n            f\"{SUPABASE_URL}/rest/v1/mrp_snapshots\",\n            headers=_sb_headers(),\n            params={\"select\": \"id,created_at\", \"calculation_key\": f\"eq.{key}\", \"limit\": \"1\"},\n            timeout=(5, 9),\n        )\n    response.raise_for_status()\n    found = response.json()\n    return found[0] if found else None\n\ndef _sb_post(payload):\n    compact = _mrp_compact_snapshot(payload)\n    key = compact[\"calculation_key\"]\n    queue = st.session_state.setdefault(\"_mrp_pending_snapshots\", {})\n    queue[key] = compact\n    last_error = None\n    try:\n        already = _mrp_lookup_saved_fast(key)\n        if already is not None:\n            queue.pop(key, None)\n            _mrp_clear_history_caches()\n            return [already]\n    except requests.exceptions.RequestException as error:\n        last_error = error\n    try:\n        response = requests.post(\n            f\"{SUPABASE_URL}/rest/v1/mrp_snapshots\",\n            headers={**_sb_headers(), \"Prefer\": \"return=minimal\"},\n            json=compact,\n            timeout=(8, 25),\n        )\n        if response.status_code == 401 and _refresh_supabase_session():\n            response = requests.post(\n                f\"{SUPABASE_URL}/rest/v1/mrp_snapshots\",\n                headers={**_sb_headers(), \"Prefer\": \"return=minimal\"},\n                json=compact,\n                timeout=(8, 25),\n            )\n        if response.status_code == 409:\n            already = _mrp_lookup_saved_fast(key)\n            if already is not None:\n                queue.pop(key, None)\n                _mrp_clear_history_caches()\n                return [already]\n        response.raise_for_status()\n        if response.status_code not in (200, 201, 204):\n            raise RuntimeError(f\"Resposta inesperada do Supabase: HTTP {response.status_code}.\")\n        queue.pop(key, None)\n        _mrp_clear_history_caches()\n        return [{\"calculation_key\": key}]\n    except requests.exceptions.RequestException as error:\n        last_error = error\n    # O banco pode ter gravado, mas a resposta não chegou: verificar\n    # uma única vez antes de exibir falha, sem repetir POST automaticamente.\n    try:\n        already = _mrp_lookup_saved_fast(key)\n        if already is not None:\n            queue.pop(key, None)\n            _mrp_clear_history_caches()\n            return [already]\n    except requests.exceptions.RequestException:\n        pass\n    msg = \"Falha temporária de comunicação.\"\n    if isinstance(last_error, requests.exceptions.HTTPError):\n        resp = last_error.response\n        if resp is not None:\n            detail = \"\"\n            try:\n                body = resp.json()\n                if isinstance(body, dict):\n                    detail = str(body.get(\"code\") or body.get(\"message\") or body.get(\"error\") or \"\")\n            except (ValueError, TypeError):\n                pass\n            msg = f\"HTTP {resp.status_code}\" + (f\" — {detail[:170]}\" if detail else \"\")\n    elif isinstance(last_error, requests.exceptions.Timeout):\n        msg = \"Tempo limite de conexão atingido.\"\n    elif isinstance(last_error, requests.exceptions.ConnectionError):\n        msg = \"Conexão interrompida.\"\n    st.session_state[\"_mrp_last_save_error\"] = msg\n    raise RuntimeError(\n        f\"Histórico NÃO confirmado ({msg}). O MRP foi mantido pendente na sessão. \"\n        \"Use SALVAR PENDENTE para tentar novamente; não recalcule as cinco bases.\"\n    ) from last_error\n"
if _source.count(_compact_insert_anchor) != 1:
    raise RuntimeError("Ponto de substituição do salvamento Supabase não localizado.")
_source = _source.replace(_compact_insert_anchor, _compact_impl + "\n" + _compact_insert_anchor, 1)

# Métricas exibidas antes de enviar o histórico para a API.
_metric_match = re.search(r"^m=st\.columns\(5\);.*$", _source, flags=re.M)
_metric_insert_anchor = '# Salva apenas uma vez por conjunto de arquivos carregado.\n'
if _metric_match is None or _source.count(_metric_insert_anchor) != 1:
    raise RuntimeError("Ponto de apresentação dos indicadores MRP não localizado.")
_metric_line = _metric_match.group(0)
_source = _source.replace(_metric_line + "\n", "", 1)
_source = _source.replace(
    _metric_insert_anchor,
    _metric_line + "\n" + _metric_insert_anchor,
    1,
)

# Permite recuperar um resultado salvo no Excel completo, mesmo depois
# do reinício do Streamlit. Não recalcula nem reinterpreta as bases.
_restore_anchor = 'if not all([cadastro_file,estoque_file,geral_file,compras_file,mt_file]):\n'
_restore_ui = ""
if _source.count(_restore_anchor) != 1:
    raise RuntimeError("Ponto de restauração do histórico não encontrado.")
_source = _source.replace(_restore_anchor, _restore_ui + "\n" + _restore_anchor, 1)

'''
